import java.util.*;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long mod = 998244353;
        long n = sc.nextLong();
        long m = sc.nextLong();
        int k = sc.nextInt();
        m = qmod(m, mod - 2, mod);
        // Compute Stirling numbers of the second kind for row k only using 1D array
        long[] S = new long[k + 1];
        S[0] = 0; // S[0][0] = 0, but we don't use S[0]
        if (k >= 1) S[1] = 1; // S[1][1] = 1
        for (int i = 2; i <= k; i++) {
            // Update from high to low to avoid overwriting
            for (int j = i; j >= 1; j--) {
                if (j == i) {
                    S[j] = 1;
                } else {
                    S[j] = (S[j] * j % mod + S[j - 1]) % mod;
                }
            }
        }
        long[] dp = new long[5005];
        dp[0] = 1;
        int limit = (int) Math.min(n, k);
        for (int i = 1; i <= limit; i++) {
            dp[i] = dp[i - 1] * (n - i + 1) % mod;
        }
        long ans = 0;
        for (int i = 1; i <= limit; i++) {
            ans = (ans + dp[i] * qmod(m, i, mod) % mod * S[i] % mod) % mod;
        }
        System.out.println(ans);
    }
    public static long qmod(long a, long b, long mod) {
        long ans = 1;
        while (b >= 1) {
            if ((b & 1) != 0) {
                ans = ans * a % mod;
            }
            a = a * a % mod;
            b = b >> 1;
        }
        return ans;
    }
}
